function [txGrid, f_list, N_subc, M_symbols] = LTE_generate(N_RB, N_subframes, f_c)
% GENERATE_LTE_UL_GRID 使用 lteToolbox 生成符合 3GPP 标准的 LTE 上行资源网格
% 输入参数:
%   N_RB        - 资源块数量 (如 15 RB 对应 3MHz 带宽) 1RB下有12个子载波
%   N_subframes - 仿真的子帧数量 (1个子帧 = 1ms = 14个OFDM符号) 
%   f_c         - 中心频点 (Hz)
% 输出参数:
%   txGrid      - 生成的完整频域资源网格 (N_subc x M_symbols)
%   f_list      - 每个子载波对应的绝对物理频率 (N_subc x 1)
%   N_subc      - 总子载波数
%   M_symbols   - 总符号数(快拍数)
% Generated by MATLAB(R) 25.2 (R2025b) and LTE Toolbox 25.2 (R2025b).
% Generated on: 07-Apr-2026 03:03:14

%% 正在生成 Uplink RMC 波形
% Uplink RMC 配置
cfg = struct('RC', 'A3-7', ...
    'NULRB', N_RB, ...
    'DuplexMode', 'FDD', ...
    'NCellID', 0, ...
    'RNTI', 1, ...
    'TotSubframes', N_subframes, ...
    'NTxAnts',1,...
    'Windowing', 0);

cfg.PUSCH.RVSeq = [0 2 3 1];
cfg = lteRMCUL(cfg);

% input bit source:
in = [1; 0; 0; 1];

% 生成
[~, igrid, cfg] = lteRMCULTool(cfg, in);

Fs = cfg.SamplingRate; 								 % 以 Hz 为单位指定波形的采样率
txGrid = squeeze(igrid); %grid = N_sub x M_symbols x NTxAnts，单天线
[N_subc, M_symbols] = size(txGrid);

delta_f = 15e3; % LTE 子载波间隔为 15 kHz
% 生成基带子载波索引
k = (-N_subc/2 : N_subc/2 - 1).';
% 注意：LTE 上行链路存在 7.5 kHz (0.5 * delta_f) 的直流偏移
% 将基带频率加上中心频率 f_c 得到绝对物理频率
f_list = f_c + (k + 0.5) * delta_f;
% %% 可视化
% % 3D Spectrogram
%  figure;
%  ax = axes;
%  surf(ax, abs(txGrid), 'EdgeColor', 'none');
%  zlabel(ax, 'Power (W)');
%  ylabel(ax, 'Subcarrier index');
%  xlabel(ax, 'OFDM symbol index');
% % 2. 静态绝对物理功率谱图 
% figure('Color', 'w', 'Name', 'Power Spectrum');
% 
% % (a) 使用 pwelch 估计基带信号的功率谱密度 (PSD)
% % 'centered' 参数让 0Hz 位于数组正中心
% [pxx, f_baseband] = pwelch(waveform, hamming(512), 256, 1024, Fs, 'centered');
% 
% % (b) 将数学上的基带频率 (围绕0Hz) 平移到真实的物理中心频点 (2.4GHz)
% f_absolute = f_baseband + f_c; 
% 
% % (c) 将功率转换为对数 dB 域
% pxx_db = 10 * log10(pxx);
% 
% % (d) 绘图 
% plot(f_absolute / 1e6, pxx_db, 'b-', 'LineWidth', 1.5);
% grid on;
% 
% % 坐标轴修饰
% xlabel('Absolute Frequency (MHz)', 'FontWeight', 'bold');
% ylabel('Power Spectral Density (dB/Hz)', 'FontWeight', 'bold');
% title(sprintf('LTE Uplink Signal Spectrum (Center: %.2f GHz)', f_c / 1e9), 'FontSize', 13);
% xlim([2385,2415]);
% 提取第 1 个子帧的第 1 个 DMRS 导频列（即第 4 个符号）
pilot_sequence = txGrid(:, 4); 

% 画出它在复平面上的样子
figure('Name', 'DMRS Pilot Constellation');
scatter(real(pilot_sequence), imag(pilot_sequence), 'b.');
axis equal;
grid on;
title('ZC Sequence Constellation (Always on Unit Circle)');
xlabel('Real Part');
ylabel('Imaginary Part');
end
